mapper.select:
SELECT d.knowledge_base_id, kb.department_id
FROM document d JOIN knowledge_base kb ON kb.id = d.knowledge_base_id JOIN document_version v ON
v.document_id = d.id AND v.version_no = #{version}
WHERE d.id = #{id}

SELECT id, chunk_type, chunk_index
FROM document_chunk
WHERE document_id = #{id} AND document_version = #{version}

SELECT id, document_id, document_version, knowledge_base_id, department_id, parent_chunk_id, chunk_type,
chunk_index, content, token_count, page_number, chapter, section, metadata::text AS metadata_json
FROM document_chunk
WHERE document_id = #{id} AND document_version = #{version} AND deleted = false

    AND chunk_type = #{type}

ORDER BY chunk_index
LIMIT #{limit}
OFFSET #{offset}

mapper.delete:
DELETE
FROM document_embedding_result
WHERE document_id=#{id} AND document_version=#{version}
